import httpx

BASE_URL = "https://api.openweathermap.org/data/2.5/weather"


class WeatherAPIError(Exception):
    pass


def fetch_weather(city: str, api_key: str, units: str = "metric") -> dict:
    params = {
        "q": city,
        "appid": api_key,
        "units": units,
    }
    response = httpx.get(BASE_URL, params=params, timeout=10)

    if response.status_code == 401:
        raise WeatherAPIError("Invalid API key. Check your OPENWEATHER_API_KEY.")
    if response.status_code == 404:
        raise WeatherAPIError(f"City '{city}' not found.")
    if response.status_code != 200:
        raise WeatherAPIError(f"API error (HTTP {response.status_code}): {response.text}")

    return response.json()

import os
import sys

import click

from weather_cli.api import WeatherAPIError, fetch_weather
from weather_cli.display import render_weather


@click.command()
@click.argument("city")
@click.option(
    "--units",
    type=click.Choice(["metric", "imperial", "standard"], case_sensitive=False),
    default="metric",
    help="Unit system for temperature and wind speed.",
)
@click.option(
    "--api-key",
    envvar="OPENWEATHER_API_KEY",
    help="OpenWeatherMap API key (or set OPENWEATHER_API_KEY).",
)
def main(city: str, units: str, api_key: str | None) -> None:
    """Show current weather for CITY."""
    if not api_key:
        click.echo("Error: Missing API key. Pass --api-key or set OPENWEATHER_API_KEY.", err=True)
        sys.exit(1)

    try:
        data = fetch_weather(city, api_key, units)
    except WeatherAPIError as exc:
        click.echo(f"Error: {exc}", err=True)
        sys.exit(1)

    render_weather(data, units)

import httpx
import pytest
import respx

from weather_cli.api import BASE_URL, WeatherAPIError, fetch_weather

SAMPLE_RESPONSE = {
    "name": "London",
    "sys": {"country": "GB"},
    "weather": [{"main": "Clouds", "description": "overcast clouds"}],
    "main": {"temp": 12.5, "feels_like": 11.0, "humidity": 80},
    "wind": {"speed": 3.2},
}


@respx.mock
def test_fetch_weather_success():
    respx.get(BASE_URL).mock(return_value=httpx.Response(200, json=SAMPLE_RESPONSE))

    result = fetch_weather("London", "fake-key")

    assert result["name"] == "London"
    assert result["main"]["temp"] == 12.5


@respx.mock
def test_fetch_weather_city_not_found():
    respx.get(BASE_URL).mock(return_value=httpx.Response(404, json={"message": "city not found"}))

    with pytest.raises(WeatherAPIError, match="not found"):
        fetch_weather("Nonexistent", "fake-key")


@respx.mock
def test_fetch_weather_invalid_api_key():
    respx.get(BASE_URL).mock(return_value=httpx.Response(401, json={"message": "Invalid API key"}))

    with pytest.raises(WeatherAPIError, match="Invalid API key"):
        fetch_weather("London", "bad-key")


@respx.mock
def test_fetch_weather_server_error():
    respx.get(BASE_URL).mock(return_value=httpx.Response(500, text="Internal Server Error"))

    with pytest.raises(WeatherAPIError, match="HTTP 500"):
        fetch_weather("London", "fake-key")


@respx.mock
def test_fetch_weather_passes_units():
    route = respx.get(BASE_URL).mock(return_value=httpx.Response(200, json=SAMPLE_RESPONSE))

    fetch_weather("London", "fake-key", units="imperial")

    assert route.calls[0].request.url.params["units"] == "imperial"

