        },
        {
            "dt_txt": "2025-01-16 12:00:00",
            "main": {"temp": 12.0, "humidity": 60},
            "weather": [{"main": "Clouds", "description": "scattered clouds"}],
            "wind": {"speed": 3.0},
        },
    ],
