    respx.get(BASE_URL).mock(return_value=httpx.Response(500, text="Internal Server Error"))

    with pytest.raises(WeatherAPIError, match="HTTP 500"):
        fetch_weather("London", "fake-key")


@respx.mock
def test_fetch_weather_passes_units():
    route = respx.get(BASE_URL).mock(return_value=httpx.Response(200, json=SAMPLE_RESPONSE))

    fetch_weather("London", "fake-key", units="imperial")

    assert route.calls[0].request.url.params["units"] == "imperial"


@respx.mock
def test_fetch_forecast_success():
    respx.get(FORECAST_URL).mock(return_value=httpx.Response(200, json=SAMPLE_FORECAST))

    result = fetch_forecast("London", "fake-key")

    assert result["city"]["name"] == "London"
    assert len(result["list"]) == 3


@respx.mock
def test_fetch_weather_connect_error():
    respx.get(BASE_URL).mock(side_effect=httpx.ConnectError("connection refused"))

    with pytest.raises(WeatherAPIError, match="Could not connect"):
        fetch_weather("London", "fake-key")


@respx.mock
def test_fetch_weather_timeout():
    respx.get(BASE_URL).mock(side_effect=httpx.ReadTimeout("read timed out"))

    with pytest.raises(WeatherAPIError, match="timed out"):
        fetch_weather("London", "fake-key")

